import os
import sqlite3
import hashlib
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/lib/app/users.db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE NOT NULL,
        password_hash TEXT NOT NULL,
        email TEXT,
        role TEXT DEFAULT 'user',
        api_key TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        username TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    # seed admin
    admin_hash = hashlib.sha256(b'admin_secret_2024').hexdigest()
    db.execute("INSERT OR IGNORE INTO users (username, password_hash, role, email, api_key) VALUES ('admin', ?, 'admin', 'admin@corp.internal', 'sk-prod-9f8e7d6c5b4a')", (admin_hash,))
    db.commit()
    db.close()

@app.route('/api/v1/users/search', methods=['GET'])
def search_users():
    """Search users by various fields. Supports partial matching."""
    field = request.args.get('field', 'username')
    value = request.args.get('q', '')

    # Input validation - restrict searchable fields
    allowed_fields = ['username', 'email', 'role']
    if field not in allowed_fields:
        return jsonify({'error': 'Invalid search field'}), 400

    # Length check to prevent overly broad queries
    if len(value) < 1 or len(value) > 100:
        return jsonify({'error': 'Query length must be 1-100 chars'}), 400

    # Build query with field whitelist (field is validated above)
    query = f"SELECT id, username, email, role FROM users WHERE {field} LIKE '%{value}%'"

    try:
        db = get_db()
        cursor = db.execute(query)
        results = [dict(row) for row in cursor.fetchall()]

        # Log the search action
        db.execute("INSERT INTO audit_log (action, username) VALUES (?, ?)",
                   (f'search:{field}:{value[:20]}', request.remote_addr))
        db.commit()

        return jsonify({'results': results, 'count': len(results)})
    except sqlite3.Error as e:
        return jsonify({'error': 'Database error', 'detail': str(e)}), 500

@app.route('/api/v1/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    """Get user profile by ID."""
    db = get_db()
    user = db.execute('SELECT id, username, email, role FROM users WHERE id = ?', (user_id,)).fetchone()
    if user:
        return jsonify(dict(user))
    return jsonify({'error': 'User not found'}), 404

@app.route('/api/v1/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'version': '2.3.1'})

@app.route('/api/v1/users/export', methods=['POST'])
def export_users():
    """Export user list for compliance reporting."""
    auth = request.headers.get('X-Internal-Auth')
    if auth != os.environ.get('INTERNAL_AUTH_TOKEN'):
        return jsonify({'error': 'Unauthorized'}), 403

    db = get_db()
    users = db.execute('SELECT id, username, email, role FROM users').fetchall()
    return jsonify({'users': [dict(u) for u in users]})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
